//! The header of a diagram: its first lines, Mermaid comments that say how
//! it stays true to the code.
//!
//! ```text
//! %% generated by crates/diagrams/tests/crates.rs; do not edit
//! %% checked against crates/types, crates/engine
//! %% drawn from engine::qualify::qualify#3f9a0c21, types::Qualification::verdict#77c0e1d4
//! %% shows every variant of proxy::Error but Task
//! ```
//!
//! Every comment line before the diagram's type is a header line, and must
//! be one of these; a block in `docs/` needs at least one. Mermaid skips
//! `%%` lines, so the header does not show on the rendered page.
//!
//! ```
//! use diagrams::header::Header;
//!
//! let text = "%% checked against crates/types\n%% drawn from types::Ticket#0a1b2c3d\nclassDiagram\n";
//! let header = Header::parse(text).unwrap();
//! assert_eq!(header.checked.as_ref().unwrap().value.crates, ["crates/types"]);
//! assert_eq!(header.drawn[0].path, "types::Ticket");
//! assert_eq!(header.drawn[0].stamp.as_deref(), Some("0a1b2c3d"));
//! assert_eq!(header.lines, 2);
//! ```

/// What a header says.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Header {
    /// `generated by <program>; do not edit`: the program that writes the
    /// block, as a path from the repository root.
    pub generated: Option<Directive<String>>,
    /// `checked against <crate directories>`.
    pub checked: Option<Directive<Checked>>,
    /// `drawn from <item>#<stamp>, …`, one entry per item.
    pub drawn: Vec<Stamped>,
    /// `shows every variant of <enum> but <variants>`.
    pub shows: Option<Directive<ShowsEvery>>,
    /// How many lines the header has.
    pub lines: usize,
}

/// A header directive and the line it is on (from 1, within the block).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Directive<T> {
    /// What it says.
    pub value: T,
    /// Its line within the block, from 1.
    pub line: usize,
}

/// `checked against …`: the crates whose source the diagram is compared
/// with.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Checked {
    /// Crate directories, relative to the repository root.
    pub crates: Vec<String>,
}

/// One item of `drawn from …`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Stamped {
    /// The item's path from its crate's name: `engine::qualify::qualify`.
    pub path: String,
    /// The stamp written after `#`, if any.
    pub stamp: Option<String>,
    /// Its line within the block, from 1.
    pub line: usize,
}

/// `shows every variant of <enum> but <variants>`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ShowsEvery {
    /// The enum's path from its crate's name: `proxy::Error`.
    pub path: String,
    /// The variants the diagram leaves out on purpose.
    pub except: Vec<String>,
}

/// A header line that is none of the directives, or one written wrong.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct HeaderError {
    /// Its line within the block, from 1.
    pub line: usize,
    /// What is wrong.
    pub message: String,
}

/// The header lines' forms, for messages.
pub const FORMS: &str = "`%% generated by <file>; do not edit`, `%% checked against <crate dir>, …`, \
`%% drawn from <crate>::<path>#<stamp>, …` or `%% shows every variant of <crate>::<enum> but <variant>, …`";

impl Header {
    /// Reads the header of a block's text. A block without one gives an
    /// empty header ([`Header::is_empty`]).
    pub fn parse(text: &str) -> Result<Header, HeaderError> {
        let mut header = Header::default();
        for (index, raw) in text.lines().enumerate() {
            let line = index + 1;
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                break;
            }
            let Some(comment) = trimmed.strip_prefix("%%") else {
                break;
            };
            // A Mermaid directive (`%%{init: …}%%`) is no comment.
            if comment.starts_with('{') {
                break;
            }
            header.lines = line;
            header.read(comment.trim(), line)?;
        }
        Ok(header)
    }

    /// Whether the block has no header at all.
    pub fn is_empty(&self) -> bool {
        self.generated.is_none()
            && self.checked.is_none()
            && self.drawn.is_empty()
            && self.shows.is_none()
    }

    fn read(&mut self, comment: &str, line: usize) -> Result<(), HeaderError> {
        let error = |message: String| HeaderError { line, message };
        if let Some(rest) = comment.strip_prefix("generated by ") {
            let program = rest
                .strip_suffix("; do not edit")
                .ok_or_else(|| error("a generated block says `; do not edit` at the end".into()))?
                .trim();
            if program.is_empty() || self.generated.is_some() {
                return Err(error("`generated by` names one program, once".into()));
            }
            self.generated = Some(Directive {
                value: program.to_owned(),
                line,
            });
        } else if let Some(rest) = comment.strip_prefix("checked against ") {
            let crates = list(rest);
            if crates.is_empty() || self.checked.is_some() {
                return Err(error(
                    "`checked against` names crate directories, once".into(),
                ));
            }
            self.checked = Some(Directive {
                value: Checked { crates },
                line,
            });
        } else if let Some(rest) = comment.strip_prefix("drawn from ") {
            let items = list(rest);
            if items.is_empty() {
                return Err(error("`drawn from` names at least one item".into()));
            }
            for item in items {
                let (path, stamp) = match item.split_once('#') {
                    Some((path, stamp)) => (path.trim().to_owned(), Some(stamp.trim().to_owned())),
                    None => (item, None),
                };
                if !is_item_path(&path) {
                    return Err(error(format!(
                        "`{path}` is no item path; write it from the crate's name, as in `engine::qualify::qualify`"
                    )));
                }
                if let Some(stamp) = &stamp
                    && !(stamp.len() == 8 && stamp.chars().all(|c| c.is_ascii_hexdigit()))
                {
                    return Err(error(format!(
                        "`#{stamp}` is no stamp; a stamp is 8 hex digits"
                    )));
                }
                self.drawn.push(Stamped { path, stamp, line });
            }
        } else if let Some(rest) = comment.strip_prefix("shows every variant of ") {
            let (path, except) = match rest.split_once(" but ") {
                Some((path, except)) => (path.trim(), list(except)),
                None => (rest.trim(), Vec::new()),
            };
            if !is_item_path(path) || self.shows.is_some() {
                return Err(error(
                    "`shows every variant of` names one enum, as in `proxy::Error`, once".into(),
                ));
            }
            self.shows = Some(Directive {
                value: ShowsEvery {
                    path: path.to_owned(),
                    except,
                },
                line,
            });
        } else {
            return Err(error(format!(
                "`%% {comment}` is no header line; the lines before the diagram's type are one of {FORMS}"
            )));
        }
        Ok(())
    }
}

/// A comma-separated list, each entry trimmed, empty ones dropped.
fn list(text: &str) -> Vec<String> {
    text.split(',')
        .map(str::trim)
        .filter(|entry| !entry.is_empty())
        .map(str::to_owned)
        .collect()
}

/// `crate::name` or longer, each segment an identifier.
fn is_item_path(path: &str) -> bool {
    let segments: Vec<&str> = path.split("::").collect();
    segments.len() >= 2
        && segments.iter().all(|segment| {
            let mut chars = segment.chars();
            chars
                .next()
                .is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
                && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
        })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_directive_reads() {
        let text = "%% generated by crates/diagrams/tests/crates.rs; do not edit\n\
                    %% checked against crates/a, crates/b\n\
                    %% drawn from a::f#0123abcd, b::T::m\n\
                    %% shows every variant of a::Error but Task, Io\n\
                    flowchart TD\n";
        let header = Header::parse(text).unwrap();
        assert_eq!(
            header.generated.unwrap().value,
            "crates/diagrams/tests/crates.rs"
        );
        assert_eq!(
            header.checked.unwrap().value.crates,
            ["crates/a", "crates/b"]
        );
        assert_eq!(header.drawn.len(), 2);
        assert_eq!(header.drawn[1].stamp, None);
        let shows = header.shows.unwrap();
        assert_eq!(shows.value.except, ["Task", "Io"]);
        assert_eq!(shows.line, 4);
        assert_eq!(header.lines, 4);
    }

    #[test]
    fn no_header_is_empty() {
        let header = Header::parse("flowchart TD\n%% checked against crates/a\n").unwrap();
        assert!(header.is_empty());
    }

    #[test]
    fn an_unknown_comment_in_the_header_is_refused() {
        let err =
            Header::parse("%% checked against crates/a\n%% a note\nclassDiagram\n").unwrap_err();
        assert_eq!(err.line, 2);
        assert!(err.message.contains("no header line"), "{}", err.message);
    }

    #[test]
    fn bad_stamps_and_paths_are_refused() {
        assert!(Header::parse("%% drawn from a::f#xyz\n").is_err());
        assert!(Header::parse("%% drawn from f#01234567\n").is_err());
        assert!(Header::parse("%% generated by x\n").is_err());
    }
}
